import unittest
from pricing import discount
import random
import itertools
class TestDiscount(unittest.TestCase):
    def test_fuzz_discount(self):
        for _ in itertools.repeat(None, 500):
            price = random.Random(1234).randint(-1000, 1000)
            pct = random.Random(1234).randint(-1000, 1000)
            self.assertEqual(discount(price, pct), price * pct / 100)
if __name__ == '__main__':
    unittest.main()

